const fs = require\('fs'\);
const path = require\('path'\);

function fixFile\(filePath\) {
  if \(!fs.existsSync\(filePath\)\) { console.log\('SKIP:', filePath\); return; }

  let content = fs.readFileSync\(filePath, 'utf8'\);
  const lines = content.split\('\\n'\);

  const asyncPattern = /^\(\\s*\)\(const\\s+\\w+\\s*=\\s*\)\(async\\s+\)\(\\\([^\)]*\\\)\\s*=>\\s*\\{\)/;
  const callbackPattern = /^\(\\s*\)\(const\\s+\\w+\\s*=\\s*useCallback\\\(\)\(async\\s+\)\(\\\([^\)]*\\\)\\s*=>\\s*\\{\)/;

  let i = 0;
  let modified = false;

  while \(i < lines.length\) {
    let match = lines[i].match\(asyncPattern\) || lines[i].match\(callbackPattern\);
    if \(match\) {
      let braceCount = 0;
      let hasAwait = false;
      let startLine = i;

      for \(let j = i; j < lines.length; j++\) {
        for \(let c = 0; c < lines[j].length; c++\) {
          if \(lines[j][c] === '{'\) braceCount++;
          if \(lines[j][c] === '}'\) braceCount--;
        }

        let lineToCheck = \(j === i\) ? lines[j].replace\(/async\\s+\\\(/, '\('\) : lines[j];
        if \(lineToCheck.match\(/\\bawait\\b/\)\) hasAwait = true;

        if \(braceCount === 0\) {
          if \(!hasAwait\) {
            lines[startLine] = lines[startLine].replace\(/async\\s+\(\\\([^\)]*\\\)\\s*=>\\s*\\{\)/, '$1'\);
            console.log\('  Removed async from line ' + \(startLine + 1\) + ': ' + lines[startLine].trim\(\).substring\(0, 70\)\);
            modified = true;
          }
          break;
        }
      }
    }
    i++;
  }

  if \(modified\) {
    fs.writeFileSync\(filePath, lines.join\('\\n'\), 'utf8'\);
    console.log\('Fixed:', filePath\);
  } else {
    console.log\('No changes needed:', filePath\);
  }
}

